import java.util.Scanner;

public class Main {
    static final int MAX = 300005;
    static long[][] dpArr = new long[27][MAX];
    static int[] fact = new int[MAX];
    static int[] invFact = new int[MAX];

    static long modPow(long base, int exp, int mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static int perm(int n, int m, int mod) {
        return (int)((long)fact[n] * invFact[n - m] % mod);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int K = sc.nextInt();
        int MOD = sc.nextInt();

        if (n % 2 != 0) {
            System.out.println(modPow(K, n, MOD));
            sc.close();
            return;
        }

        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (int)((long)fact[i - 1] * i % MOD);
        }

        invFact[n] = (int)modPow(fact[n], MOD - 2, MOD);
        for (int i = n - 1; i >= 0; i--) {
            invFact[i] = (int)((long)invFact[i + 1] * (i + 1) % MOD);
        }

        dpArr[0][0] = 1L;
        for (int k = 0; k < K; k++) {
            for (int i = 1; i <= n; i++) {
                if ((i & n) != i) continue;
                int block_mask = 1 << (31 - Integer.numberOfLeadingZeros(i));
                long res = 0L;
                int j = i;
                int cnt = 0;
                while (true) {
                    int j_plus = j + block_mask;
                    res += dpArr[k][i ^ j_plus] * invFact[j_plus];
                    res %= MOD;
                    cnt++;
                    if (j == 0) break;
                    j = (j - 1) & i;
                }
                dpArr[k + 1][i] = res;
            }
        }

        int answer = 0;
        for (int i = 0; i <= K; i++) {
            long temp = ((long)fact[n] * dpArr[i][n]) % MOD;
            temp = (temp * perm(K, i, MOD)) % MOD;
            answer = (int)((answer + temp) % MOD);
        }

        int result = (int)((modPow(K, n, MOD) + MOD - answer) % MOD);
        System.out.println(result);
        sc.close();
    }
}
